import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:senas_core/dtw.dart';
import 'package:senas_core/plantillas.dart';
import 'package:senas_core/sign_norm.dart' show kFrameDim, kTFrames;

/// Señas solo de aprendizaje (assets/aprendizaje.json): float16 en base64,
/// fuera del clasificador.
void main() {
  test('halfADouble lee float16 como la base', () {
    expect(halfADouble(0x3800), 0.5);
    expect(halfADouble(0xBD00), -1.25);
    expect(halfADouble(0x0000), 0.0);
    expect(halfADouble(0x4000), 2.0);
    expect(halfADouble(0x3C00), 1.0);
    expect(halfADouble(0x0001), closeTo(5.96e-8, 1e-9)); // subnormal
  });

  const b64 = '';

  test('decodificarF16 devuelve 32 cuadros de 152 con los valores', () {
    final seq = decodificarF16(b64);
    expect(seq.length, kTFrames);
    expect(seq.every((f) => f.length == kFrameDim), isTrue);
    expect(seq[0][0], 0.5);
    expect(seq[0][1], -1.25);
    expect(seq[0][2], closeTo(0.1, 1e-3));
    expect(seq[0][30], 1.0);
  });

  test('leerAprendizaje arma plantillas y salta las corruptas', () {
    final texto = jsonEncode({
      'norm_version': '2.0.0',
      't_frames': 32,
      'frame_dim': 152,
      'forma': 'iso1',
      'uso': 'aprendizaje',
      'codificacion': 'f16le-base64',
      'plantillas': [
        {'sign_id': 's1', 'gloss': 'ZAPATOS', 'espanol': 'Zapatos', 'seq_f16': b64},
        {'sign_id': 's2', 'gloss': 'ROTA', 'espanol': 'x', 'seq_f16': '!!!'},
      ],
    });
    final t = leerAprendizaje(texto);
    expect(t, hasLength(1));
    expect(t.single.gloss, 'ZAPATOS');
    expect(t.single.espanol, 'Zapatos');
    // La altura no se toca: la muñeca izquierda (y) queda igual que en el archivo.
    expect(t.single.seq[3][25], decodificarF16(b64)[3][25]);
  });

  test('otro formato o version: lista vacia', () {
    expect(leerAprendizaje(jsonEncode({'norm_version': '1.0.0', 'plantillas': []})), isEmpty);
  });

  test('el Diccionario las lleva aparte del clasificador', () {
    final c = DtwClassifier();
    final d = Diccionario(
      c,
      const ResumenDiccionario(
          delPaquete: 0, sincronizadas: 0, locales: 0, espejadas: 0, senasDistintas: 0),
      aprendizaje: [Template('s1', 'ZAPATOS', decodificarF16(b64), espanol: 'Zapatos')],
    );
    expect(d.aprendizaje.single.gloss, 'ZAPATOS');
    expect(c.templates, isEmpty);
  });
}
